-   $2f_{i,1}-f_{i,2}=3+f_{i+1,1}$
-   $3f_{i,j}-f_{i,j-1}-f_{i,j+1}=4+f_{i+1,j}$
-   $2f_{i,m}-f_{i,m-1}=3+f_{i+1,m}$

由于是逆序的递推，所以每一个 $f_{i+1,j}$ 是已知的。
由于有 $m$ 列，所以右边相当于是一个 $m$ 行的列向量，那么左边就是 $m$ 行 $m$ 列的矩阵。使用增广矩阵，就变成了 m 行 m+1 列的矩阵，然后进行 [高斯消元](../math/numerical/gauss.md) 即可解出答案。

### 实现

??? note "参考实现"
    ```c++
    #include <bits/stdc++.h>
    using namespace std;

    const int maxn = 1e3 + 10;

    double a[maxn][maxn], f[maxn];
    int n, m;

    void solve(int x) {
      memset(a, 0, sizeof a);
      for (int i = 1; i <= m; i++) {
        if (i == 1) {
          a[i][i] = 2;
          a[i][i + 1] = -1;
          a[i][m + 1] = 3 + f[i];
          continue;
        } else if (i == m) {
          a[i][i] = 2;
          a[i][i - 1] = -1;
          a[i][m + 1] = 3 + f[i];
          continue;
        }
        a[i][i] = 3;
        a[i][i + 1] = -1;
        a[i][i - 1] = -1;
        a[i][m + 1] = 4 + f[i];
      }

      for (int i = 1; i < m; i++) {
        double p = a[i + 1][i] / a[i][i];
        a[i + 1][i] = 0;
        a[i + 1][i + 1] -= a[i][i + 1] * p;
        a[i + 1][m + 1] -= a[i][m + 1] * p;
      }

      f[m] = a[m][m + 1] / a[m][m];
      for (int i = m - 1; i >= 1; i--)
        f[i] = (a[i][m + 1] - f[i + 1] * a[i][i + 1]) / a[i][i];
    }

    int main() {
      scanf("%d %d", &n, &m);
      int st, ed;
      scanf("%d %d", &st, &ed);
      if (m == 1) {
        printf("%.10f\n", 2.0 * (n - st));
        return 0;
      }
      for (int i = n - 1; i >= st; i--) {
        solve(i);
      }
      printf("%.10f\n", f[ed]);
      return 0;
    }

