      sort(id + 2, id + n + 1, [](int x, int y) { return dep[x] < dep[y]; });

      for (i = 2; i <= n; ++i) {
        dfs(1);
        solve(1, id[i]);
      }

      printf("!");
      for (i = 2; i <= n; ++i) printf(" %d", fa[i]);
      printf("\n");
      fflush(stdout);

