## 实例

### 模板

> 有 $n$ 个物品，每个物品有两个权值 $a$ 和 $b$。求一组 $w_i\in\{0,1\}$，最大化 $\displaystyle\frac{\sum a_i\times w_i}{\sum b_i\times w_i}$ 的值。

把 $a_i-mid\times b_i$ 作为第 $i$ 个物品的权值，贪心地选所有权值大于 $0$ 的物品即可得到最大值。

为了方便初学者理解，这里放上完整代码：

??? 参考代码
    ```cpp
    #include <algorithm>
    #include <cmath>
    #include <cstdio>
    #include <cstdlib>
    #include <cstring>
    #include <iostream>
    using namespace std;

    int read() {
      int X = 0, w = 1;
      char c = getchar();
      while (c < '0' || c > '9') {
        if (c == '-') w = -1;
        c = getchar();
      }
      while (c >= '0' && c <= '9') X = X * 10 + c - '0', c = getchar();
      return X * w;
    }

    const int N = 100000 + 10;
    const double eps = 1e-6;

    int n;
    double a[N], b[N];

    bool check(double mid) {
      double s = 0;
      for (int i = 1; i <= n; ++i)
        if (a[i] - mid * b[i] > 0)  // 如果权值大于 0
          s += a[i] - mid * b[i];   // 选这个物品
      return s > 0;
    }

    int main() {
      // 输入
      n = read();
      for (int i = 1; i <= n; ++i) a[i] = read();
      for (int i = 1; i <= n; ++i) b[i] = read();
      // 二分
      double L = 0, R = 1e9;
      while (R - L > eps) {
        double mid = (L + R) / 2;
        if (check(mid))  // mid 可行，答案比 mid 大
          L = mid;
        else  // mid 不可行，答案比 mid 小
          R = mid;
      }
      // 输出
      printf("%.6lf\n", L);
      return 0;
    }

```

